async fn cast_send_zk<P: Provider<T, AnyNetwork>, T: Transport + Clone>(
    provider: P,
    tx: impl AsRef<[u8]>,
    cast_async: bool,
    confs: u64,
    timeout: u64,
    to_json: bool,
) -> Result<()> {
    let tx_hash = provider.send_raw_transaction(tx.as_ref()).await?.tx_hash().to_owned();
    let cast = Cast::new(provider);

    handle_transaction_result(&cast, &tx_hash, cast_async, confs, timeout, to_json).await
}

